$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$base='http://192.168.122.1:8872';$out='C:\JudasValidation\M78ClosureResults';$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-closure-completed-project-approval-v2.json").Content|ConvertFrom-Json;if(!$m.hostVerified){throw 'Independent host exact verification required'};$allowed=@('balance-step-trace','balance-radial','balance-lifecycle','balance-cold-stand','balance-cold-recovery','ordinary-actual-stand','ordinary-actual-recovery');$before=(Get-PSDrive C).Free;foreach($r in $m.rows){if($r.project -notin @($allowed|ForEach-Object {"$out\$_\project"})){throw 'Path outside named authorization'};if((Get-Item $r.archive).Length -ne $r.bytes -or(Get-FileHash $r.archive).Hash.ToLower() -ne $r.sha256){throw 'Archive changed'};foreach($f in $r.files){$p=Join-Path $r.project $f.path;if((Get-Item $p).Length -ne $f.bytes -or(Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw 'Per-file retired bytes changed'}};if(@(Get-ChildItem $r.project -Recurse -File).Count -ne $r.files.Count){throw 'Unexpected project file'}};foreach($r in $m.rows){Remove-Item -LiteralPath $r.project -Recurse};$rp="$out\m78-closure-completed-project-retirement-v2.json";@{scope='Exactly approved seven completed new copied projects only, lossless host ZIP and every logical file SHA/size verified. All snapshot/JSON/logs and original projects/packages/source untouched';rows=$m.rows;freeBefore=$before;freeAfter=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content $rp -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$([IO.Path]::GetFileName($rp))" -Method Post -InFile $rp|Out-Null
